  // ---------- 成长追踪（/history 顶部，2026-10-27） ----------
  //
  // 数据来自 /api/growth（只读聚合）。曲线只画**已评分**的场次，且只画**同一岗位**
  // —— 不同岗位的分数不在一个尺度上，混在一起画会得出错误的"进步"结论。
  var growthRole = "";
  var growthFingerprint = "";

  function growthDate(ts) {
    if (!ts) { return "—"; }
    var d = new Date(ts * 1000);
    return (d.getMonth() + 1) + "/" + d.getDate();
  }

  function loadGrowth() {
    fetch("/api/growth?limit=50", { cache: "no-store" })
      .then(function (r) { if (!r.ok) { throw new Error("HTTP " + r.status); } return r.json(); })
      .then(function (all) {
        var points = all.points || [];
        var scored = points.filter(function (p) { return typeof p.total === "number"; });
        if (!scored.length) { renderGrowthEmpty(); return; }
        var roles = [];
        for (var i = 0; i < points.length; i++) {
          if (points[i].role && roles.indexOf(points[i].role) < 0) { roles.push(points[i].role); }
        }
        if (!growthRole || roles.indexOf(growthRole) < 0) {
          growthRole = scored[scored.length - 1].role || "";
        }
        loadGrowthFor(growthRole, roles);
      })
      .catch(function () { /* 静默：状态栏由 loadList 负责 */ });
  }

  function loadGrowthFor(role, roles) {
    var url = "/api/growth?limit=20" + (role ? "&role=" + encodeURIComponent(role) : "");
    fetch(url, { cache: "no-store" })
      .then(function (r) { return r.json(); })
      .then(function (d) { renderGrowth(d, role, roles || []); })
      .catch(function () {});
  }

  function renderGrowthEmpty() {
    elGrowth.style.display = "block";
    elGrowth.innerHTML =
      '<div class="growth">' +
        '<div class="growth-head"><h2>成长追踪</h2>' +
          '<span class="growth-sub">完成 2 场带评分的面试后，这里会画出你的进步曲线</span></div>' +
      '</div>';
  }

  function renderGrowth(d, role, roles) {
    var points = (d.points || []).filter(function (p) { return typeof p.total === "number"; });
    if (points.length < 2) { renderGrowthEmpty(); return; }

    var W = 640, H = 190, L = 34, R = 14, T = 14, B = 26;
    var iw = W - L - R, ih = H - T - B;
    var xs = function (i) { return L + (points.length === 1 ? iw / 2 : (i / (points.length - 1)) * iw); };
    var ys = function (v) { return T + ih * (1 - Math.max(0, Math.min(100, v)) / 100); };

    var svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="总分随场次变化">';
    // 网格 + y 轴刻度（退到背景层）
    [0, 25, 50, 75, 100].forEach(function (v) {
      var y = ys(v);
      svg += '<line x1="' + L + '" y1="' + y + '" x2="' + (W - R) + '" y2="' + y +
        '" stroke="var(--line)" stroke-width="1"></line>';
      svg += '<text x="' + (L - 6) + '" y="' + (y + 3.5) +
        '" text-anchor="end" font-size="10" fill="var(--ink-dim)">' + v + '</text>';
    });
    // 折线
    var path = "";
    for (var i = 0; i < points.length; i++) {
      path += (i ? " " : "") + xs(i) + "," + ys(points[i].total);
    }
    svg += '<polyline points="' + path + '" fill="none" stroke="var(--brand)" ' +
      'stroke-width="2" stroke-linejoin="round" stroke-linecap="round"></polyline>';
    // 数据点（8px 直径 + 2px 表面环）+ 末点直接标注
    for (var j = 0; j < points.length; j++) {
      var isLast = j === points.length - 1;
      svg += '<circle class="gpt" data-i="' + j + '" cx="' + xs(j) + '" cy="' + ys(points[j].total) +
        '" r="' + (isLast ? 5 : 4) + '" fill="' + (isLast ? "var(--brand)" : "var(--card)") +
        '" stroke="var(--brand)" stroke-width="2"></circle>';
    }
    var last = points[points.length - 1];
    svg += '<text x="' + xs(points.length - 1) + '" y="' + (ys(last.total) - 10) +
      '" text-anchor="end" font-size="12" font-weight="600" fill="var(--ink)">' + last.total + '</text>';
    // x 轴：只标首末日期（选择性标签，不给每个点都标）
    svg += '<text x="' + xs(0) + '" y="' + (H - 6) + '" text-anchor="start" font-size="10" fill="var(--ink-dim)">' +
      growthDate(points[0].created_at) + '</text>';
    svg += '<text x="' + xs(points.length - 1) + '" y="' + (H - 6) + '" text-anchor="end" font-size="10" fill="var(--ink-dim)">' +
      growthDate(last.created_at) + '</text>';
    svg += '</svg>';

    var html = '<div class="growth">' +
      '<div class="growth-head"><h2>成长追踪</h2>' +
        '<span class="growth-sub">' + esc(role || "全部岗位") + ' · ' + points.length + ' 场</span>';
    if (roles && roles.length > 1) {
      html += '<select class="growth-role" id="growthRole">';
      for (var k = 0; k < roles.length; k++) {
        html += '<option value="' + esc(roles[k]) + '"' + (roles[k] === role ? " selected" : "") + '>' +
          esc(roles[k]) + '</option>';
      }
      html += '</select>';
    }
    html += '</div>';
    html += '<div class="growth-chart">' + svg + '<div class="growth-tip" id="growthTip"></div></div>';

    // 最近两场维度对比
    if (d.deltas && d.deltas.dimensions && d.deltas.dimensions.length) {
      var bits = [];
      if (typeof d.deltas.total === "number") {
        bits.push("总分 " + (d.deltas.total > 0 ? "+" : "") + d.deltas.total);
      }
      d.deltas.dimensions.forEach(function (dim) {
        bits.push(dim.name + " " + (dim.delta > 0 ? "+" : "") + dim.delta);
      });
      html += '<div class="growth-note">较上一场：' + bits.map(esc).join(" · ") + '</div>';
    } else {
      html += '<div class="growth-note">再完成一场带评分的面试，就能看到与上一场的维度对比。</div>';
    }

    // 薄弱点（反复失分，不是单场低分）
    if (d.weak_points && d.weak_points.length) {
      html += '<div class="growth-chips">';
      d.weak_points.forEach(function (w) {
        html += '<span class="gchip warn">' + esc(w.name) + ' 平均 ' + w.average +
          '（' + w.low_sessions + '/' + w.sessions + ' 场低于 6）</span>';
      });
      html += '</div>';
    }

    // 数据表（无图也能读）
    html += '<details><summary>数据表</summary><table><tr><th>日期</th><th>轮次</th><th>总分</th>' +
      '<th>语速</th><th>口头语</th><th>停顿</th></tr>';
    for (var q = 0; q < points.length; q++) {
      var p = points[q], ex = p.expression || {};
      html += '<tr><td>' + growthDate(p.created_at) + '</td><td>' + esc(p.rounds) +
        '</td><td>' + esc(p.total) + '</td><td>' +
        (typeof ex.avg_speed === "number" ? ex.avg_speed : "—") + '</td><td>' +
        (typeof ex.fillers === "number" ? ex.fillers : "—") + '</td><td>' +
        (typeof ex.pauses === "number" ? ex.pauses : "—") + '</td></tr>';
    }
    html += '</table></details>';
    html += '</div>';

    elGrowth.style.display = "block";
    elGrowth.innerHTML = html;

    // 岗位切换
    var sel = document.getElementById("growthRole");
    if (sel) {
      sel.onchange = function () { growthRole = sel.value; loadGrowthFor(sel.value, roles); };
    }

    // 悬停提示（十字线不画：点数少，点本身的 hover 已足够）
    var tip = document.getElementById("growthTip");
    var svgEl = elGrowth.querySelector("svg");
    var circles = elGrowth.querySelectorAll(".gpt");
    for (var c = 0; c < circles.length; c++) {
      circles[c].addEventListener("mouseenter", function (ev) {
        var idx = Number(ev.currentTarget.getAttribute("data-i"));
        var p = points[idx] || {};
        var ex = p.expression || {};
        var lines = [growthDate(p.created_at) + " · " + (p.role || "") + " · " + (p.total) + " 分"];
        if (typeof ex.avg_speed === "number") { lines.push("语速 " + ex.avg_speed + " 字/分"); }
        if (typeof ex.fillers === "number") { lines.push("口头语 " + ex.fillers + " 次"); }
        if (typeof ex.pauses === "number") { lines.push("停顿 " + ex.pauses + " 次"); }
        tip.textContent = lines.join("｜");
        tip.style.display = "block";
        var rect = svgEl.getBoundingClientRect();
        var vb = svgEl.viewBox.baseVal;
        var scale = rect.width / vb.width;
        tip.style.left = (ev.currentTarget.cx.baseVal.value * scale) + "px";
        tip.style.top = (ev.currentTarget.cy.baseVal.value * scale) + "px";
      });
      circles[c].addEventListener("mouseleave", function () { tip.style.display = "none"; });
    }
  }
