492	    if (cloud_health_check() != CLOUD_OK) {
493	        printf("[Main] 警告: 云端不可达，请检查 CLOUD_URL 与网络\n");
494	    }
495	
496	    /* 账号绑定（2026-10-27）：没绑定就申请一个 token，把二维码 URL 交给主线程。
497	     * token 同时是设备之后的长期凭据，申请到立刻落盘（重启不再重复申请）。 */
498	    if (cloud_user_token()[0] == '\0') {
499	        char bind_url[256];
