501	
502	        printf("[Main] 未绑定账号，向云端申请绑定二维码...\n");
503	        if (cloud_bind_start(bind_url, sizeof(bind_url),
504	                             bind_token, sizeof(bind_token)) == CLOUD_OK) {
505	            cloud_set_user_token(bind_token);
506	            save_user_token(bind_token);
