509	            printf("[Main] 申请绑定二维码失败（不影响面试，重启可再试）\n");
510	        }
511	    }
512	
513	    for (;;) {
514	        app_cmd_t cmd;
515	        char discard_sid[64];
516	
517	        /* ---- 待处理的"舍弃本场"通知（K2 长按设置）----
518	         * 网络调用必须留在工作线程：主循环每 100ms 一拍，塞个最多 30 秒的 HTTP
519	         * 进去，按键和 LED 都会僵住（同文件顶部的线程模型注释）。
520	         * 忙的时候它排在下一轮之后 —— 没关系：长按同时置了 g_abort，当前这一轮
521	         * 会很快退出，然后这里就把 DELETE 发出去。 */
522	        pthread_mutex_lock(&g_lock);
523	        strncpy(discard_sid, g_discard_sid, sizeof(discard_sid) - 1);
524	        discard_sid[sizeof(discard_sid) - 1] = '\0';
525	        g_discard_sid[0] = '\0';
526	        pthread_mutex_unlock(&g_lock);
527	
528	        if (discard_sid[0] != '\0') {
529	            printf("[Main] 通知云端删除本场记录（session=%s）...\n", discard_sid);
530	            if (cloud_discard_session(discard_sid) == CLOUD_OK) {
531	                printf("[Main] 云端记录已删除（/history 里不会再出现）\n");
532	            } else {
533	                printf("[Main] 警告: 云端删除失败 —— /history 里可能仍显示「进行中」\n");
534	            }
535	        }
536	
537	        pthread_mutex_lock(&g_lock);
538	        cmd = g_cmd;
539	        g_cmd = CMD_NONE;
540	        pthread_mutex_unlock(&g_lock);
541	
542	        /* 屏幕配网页提交 → 凭据已由主线程写盘（见 app_wifi_setup），
543	         * 这里只负责真正执行连接（会阻塞几秒，所以必须在本线程）。 */
544	        if (cmd == CMD_WIFI_CONNECT) {
545	            printf("[Main] 收到屏幕配网请求，开始连接...\n");
546	            if (wifi_connect_boot() == 0) {
547	                printf("[Main] Wi-Fi 连接命令已完成（以云端健康检查为准）\n");
548	            } else {
549	                printf("[Main] Wi-Fi 连接未完成 —— 可在屏幕上重新设置\n");
550	            }
551	            continue;
552	        }
553	
554	        if (cmd != CMD_START) {
555	            usleep(MAIN_LOOP_MS * 1000 / 2);
556	            continue;
557	        }
558	
559	        pthread_mutex_lock(&g_lock);
560	        g_worker_busy = 1;
561	        g_abort = 0;
562	        pthread_mutex_unlock(&g_lock);
563	
564	        run_one_round();
565	
566	        pthread_mutex_lock(&g_lock);
567	        g_worker_busy = 0;
568	        pthread_mutex_unlock(&g_lock);
569	    }
570	
571	    return NULL;
572	}
