    if (fgets(ssid, WIFI_CRED_MAX, fp) == NULL ||
        fgets(psk, WIFI_CRED_MAX, fp) == NULL) {
        fclose(fp);
        return -1;
    }
    fclose(fp);
    trim(ssid);
    trim(psk);
