#include <termios.h>

/* ---------- 串口首次配置（2026-10-31） ---------- */

static void console_echo(int enable)
{
#ifdef CONFIG_SERIAL_TERMIOS
    struct termios t;

    if (tcgetattr(STDIN_FILENO, &t) == 0) {
        if (enable) {
            t.c_lflag |= ECHO;
        } else {
            t.c_lflag &= ~ECHO;
        }
        (void)tcsetattr(STDIN_FILENO, TCSANOW, &t);
    }
#else
    (void)enable;
#endif
}

static int read_console_line(const char *prompt, char *buf, size_t cap, int hidden)
{
    size_t len;

    printf("%s", prompt);
    fflush(stdout);

    if (hidden) {
        console_echo(0);
    }

    if (fgets(buf, (int)cap, stdin) == NULL) {
        if (hidden) {
            console_echo(1);
        }
        return -1;
    }

    if (hidden) {
        console_echo(1);
        printf("\n");
    }

    trim(buf);

    /* fgets 在空行时给的是 "\n"；trim 后变空串，调用方按"跳过"处理 */
    len = strlen(buf);
    (void)len;
    return 0;
}

int wifi_serial_setup(void)
{
    char ssid[WIFI_CRED_MAX];
    char psk[WIFI_CRED_MAX];
