    printf("  首次使用：配置 Wi-Fi\n");
    printf("  直接回车可跳过（之后可在屏幕右上角 Wi-Fi 重设）\n");
    printf("========================================\n");

    for (tries = 0; tries < 3; tries++) {
        if (read_console_line("热点名称（SSID）: ", ssid, sizeof(ssid), 0) != 0) {
            return -1;
        }
        if (ssid[0] == '\0') {
            printf("[Wifi] 已跳过串口配置\n");
            return -1;
