        if (!cred_ok(ssid)) {
            printf("[Wifi] SSID 含不支持的字符（空格/引号/分号/管道等），请重试\n");
            continue;
        }

        if (read_console_line("热点密码: ", psk, sizeof(psk), 1) != 0) {
