 */
static void boot_shell_window(void)
{
    fd_set rfds;
    struct timeval tv;
    char ch;
    pid_t pid;
    int status;

    if (!isatty(STDIN_FILENO)) {
        return;
    }

    printf("[Main] 2 秒内按回车进入命令行（调试用，否则自动启动）...\n");
    fflush(stdout);

    FD_ZERO(&rfds);
    FD_SET(STDIN_FILENO, &rfds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    if (select(STDIN_FILENO + 1, &rfds, NULL, NULL, &tv) <= 0) {
        return;
    }

    /* 吃掉触发的那一个字节（一般是 '\n'），免得被后面的输入读到 */
    if (read(STDIN_FILENO, &ch, 1) != 1) {
        return;
    }

    printf("\n[Main] 进入命令行（exit 返回启动流程）\n");
    fflush(stdout);

    {
        char *argv[] = { (char *)"nsh", NULL };

        if (posix_spawn(&pid, "nsh", NULL, NULL, argv, NULL) == 0) {
            waitpid(pid, &status, 0);
        } else {
            printf("[Main] 启动 nsh 失败\n");
        }
    }

    printf("\n[Main] 返回启动流程\n");
    fflush(stdout);
