 * 为什么不经 nsh：nsh 启动时会执行 /etc/init.d/rcS，而 rcS 现在会自启
 * ai_interview；从主程序里再 spawn 一个 nsh，就会重新跑一遍 rcS →
 * 又启动一个主程序 → 无限递归（2026-10-31 真机踩到，串口刷屏）。
 * 直接 spawn 内置命令不会经过 nsh 的初始化流程。
 *
 * NuttX 的 posix_spawn 会把 argv[0] 当作任务名，argv[1..] 原样传给新任务；
 * 所以调用方按正常 argv 写即可。
 */
static int run_builtin(const char *prog, char *const argv[], const char *label)
{
    pid_t pid;
    int status = 0;
    int ret;

    ret = posix_spawn(&pid, prog, NULL, NULL, argv, NULL);
    if (ret != 0) {
        printf("[Wifi] %s: 启动 %s 失败 (%d)\n", label, prog, ret);
        return -1;
    }

    ret = (int)waitpid(pid, &status, 0);
    if (ret < 0) {
        printf("[Wifi] %s: 等待命令结束失败 (%d)\n", label, errno);
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        printf("[Wifi] %s: 命令返回异常 (status=%d)\n", label, status);
        return -1;
    }
    return 0;
