/*
 * 串口逃逸（2026-10-31）：主循环里非阻塞看 stdin，输入 `nsh` 回车就进命令行。
 *
 * 为什么不在开机时抢读 stdin：用户看到配网提示会立刻开始输入 SSID，任何
 * "按回车进 shell"的窗口都会吞字符（真机踩过）。这里只在配网完成后的主循环里
 * 检查，且用零超时 select，不阻塞、不影响正常输入。
 *
 * 从本程序 spawn 的 nsh 会重跑 rcS；rcS 里有 /tmp/ai_interview_started 防重入
 * 标记（main() 启动时也会确保它存在），所以不会再启动第二个主程序。
 */
static void check_serial_shell(void)
{
    fd_set rfds;
    struct timeval tv;
    char line[32];
    char *p;
    size_t len;
    ssize_t n;
    pid_t pid;
    int status;

    FD_ZERO(&rfds);
    FD_SET(STDIN_FILENO, &rfds);
    tv.tv_sec = 0;
    tv.tv_usec = 0;

    if (select(STDIN_FILENO + 1, &rfds, NULL, NULL, &tv) <= 0) {
        return;
    }

    n = read(STDIN_FILENO, line, sizeof(line) - 1);
    if (n <= 0) {
        return;
    }
    line[n] = '\0';

    p = line;
    while (*p == ' ' || *p == '\t') {
        p++;
    }
    len = strlen(p);
    while (len > 0 && (p[len - 1] == '\n' || p[len - 1] == '\r' ||
                       p[len - 1] == ' ' || p[len - 1] == '\t')) {
        p[--len] = '\0';
    }

    if (strcmp(p, "nsh") != 0) {
        return;     /* 其它输入忽略，不占用串口 */
    }

    printf("\n[Main] 进入命令行（exit 返回主程序）...\n");
    fflush(stdout);

    {
        char *argv[] = { (char *)"nsh", NULL };

        if (posix_spawn(&pid, "nsh", NULL, NULL, argv, NULL) == 0) {
            waitpid(pid, &status, 0);
        } else {
            printf("[Main] 启动 nsh 失败\n");
        }
    }

    printf("\n[Main] 已返回主程序\n");
    fflush(stdout);
}

