/* 见 audio_io.h 的注释。主线程（LVGL 按钮回调）也会调 —— 这里只做一次很短的
 * snd_ctl_set，不碰 PCM 句柄，和播放/录音线程可以并存。 */
void audio_set_volume(int percent)
{
    if (percent < 0) {
        percent = 0;
    }
    if (percent > 100) {
        percent = 100;
    }
    /* DACL/DACR digital volume 不是线性音量，而是按 dB 的 8 位寄存器：
     *   0x00 = 静音，0x01 = -119.25dB，0xA0(160) = 0dB，0xFF = +71.25dB，
     *   每步 0.75dB。
     * 第一版直接 `percent * 255 / 100`：60%=153(-5.25dB)，可一按 - 到 50%=127
     * 就是 **-24.75dB**、一按 + 到 70%=178 就是 **+13.5dB** —— 每 10% 约 19dB，
     * 用户实测"一按特别小 / 一按特别大"。
     * 现在把非零百分比均匀铺在 **-9dB ~ +6dB**（每 10% = 1.5dB，正好 2 个
     * 寄存器步）；0% 单独给静音。
     * 2026-10-20 用户实测"整体太小"，整条曲线上移 6dB：60%（默认）= 0dB，
     * 与旧版 100% 一样响；100% = +6dB。正增益有削顶风险，TTS 语音峰值一般
     * 在满幅以下，真机若 100% 破音就把下面的 168 回调到 166（+4.5dB），步进不动。
     */
    if (percent == 0) {
        g_dac_volume = 0;
    } else {
        g_dac_volume = (unsigned int)(168 - (100 - percent) * 2 / 10);
    }

    /* 立刻生效。codec 还没起来时可能失败 —— 不致命：这个值会被下一次
     * codec_configure 带进去（那是每轮录音都会走的路）。 */
    (void)snd_ctl_set(AI_CODEC_CARD, "DACL digital volume", g_dac_volume);
    (void)snd_ctl_set(AI_CODEC_CARD, "DACR digital volume", g_dac_volume);
    printf("[Audio] 音量设为 %d%%（DAC %u/255）\n", percent, g_dac_volume);
}

