def weighted_total(dims) -> int:
    """按权重算 0~100 总分（不四舍五入到维度平均）。

    缺维度时只对**已评维度**的权重重新归一化 —— 未考察的维度不应该按 0 分
    拉低总分（与 myagent 的 weighted_overall 同一条规则）。
    """
    total = 0.0
    weight_sum = 0.0
    for dim in dims:
        weight = DIMENSION_WEIGHTS.get(dim.get("name"), 0.0)
        total += float(dim.get("score", 0)) * weight
        weight_sum += weight
    if weight_sum <= 0:
        return 0
    return int(round(total / weight_sum * 10))


