    {
        lv_obj_t *wifi_btn = make_text_button(g_page_idle, "Wi-Fi",
                                              wifi_open_event,
                                              compact ? 74 : 100,
                                              compact ? 34 : 42,
                                              g_font_hint);
        lv_obj_align(wifi_btn, LV_ALIGN_TOP_RIGHT,
                     compact ? -6 : -18, compact ? 6 : 16);
    }
}

