499	        printf("[Main] 本轮已被 K2 取消（上传阶段）\n");
500	        cloud_response_free(&resp);
501	        app_post_event(EVENT_ERROR);         /* UPLOADING --ERROR--> IDLE */
502	        return;
503	    }
504	
505	    if (rc != CLOUD_OK) {
506	        cloud_response_free(&resp);
507	        app_post_event(EVENT_UPLOAD_FAIL);   /* -> ERROR 或 IDLE */
508	        return;
509	    }
510	
511	    /* ---- 3. 记录会话状态，供下一轮回传 ---- */
512	    pthread_mutex_lock(&g_lock);
513	    if (resp.session_id[0] != '\0') {
514	        strncpy(g_session_id, resp.session_id, sizeof(g_session_id) - 1);
515	        g_session_id[sizeof(g_session_id) - 1] = '\0';
516	    }
517	    if (resp.text != NULL) {
518	        strncpy(g_last_text, resp.text, sizeof(g_last_text) - 1);
519	        g_last_text[sizeof(g_last_text) - 1] = '\0';
520	    }
521	    pthread_mutex_unlock(&g_lock);
522	
523	    /* ASR 原文单独打一行。之前只打面试官的回复，只能从回复里反推它有没有
524	     * 听对 —— 万一识别错了，看起来就像"模型答非所问"，会把排查方向带偏。 */
525	    printf("[Main] 我听到你说: %s\n",
526	           (resp.user_text != NULL && resp.user_text[0] != '\0')
527	               ? resp.user_text : "(空)");
528	    printf("[Main] 面试官: %s\n", resp.text ? resp.text : "(无文本)");
529	
530	    app_post_event(EVENT_UPLOAD_SUCCESS);    /* UPLOADING -> PLAYING */
531	
532	    /* ---- 4. 播放 ---- */
533	    (void)audio_play_wav(resp.tts_wav, resp.tts_wav_len, &g_abort);
534	
535	    /* 面试结束则清空会话，下次 K1 开新面试 */
536	    if (strcmp(resp.next_action, "continue") != 0) {
537	        printf("[Main] 本轮面试结束（next_action=%s）\n", resp.next_action);
538	        pthread_mutex_lock(&g_lock);
539	        g_session_id[0] = '\0';
540	        pthread_mutex_unlock(&g_lock);
541	    }
542	
543	    cloud_response_free(&resp);
544	
545	    /*
546	     * 必须是本函数最后一条语句。
547	     * 若在 free 之前投递，主线程会立刻转 IDLE，用户马上按 K1 开下一轮，
548	     * 而本线程还在收尾 —— 下一轮录音与上一轮释放并发。
549	     */
550	    app_post_event(EVENT_PLAY_DONE);         /* PLAYING -> IDLE */
551	}
