553	static void *pipeline_worker(void *arg)
554	{
555	    (void)arg;
556	
557	    /* libcurl 一律只在本线程里用：它需要 200KB 量级的栈
558	     * （参考 CONFIG_EXAMPLES_HTTP_STACKSIZE 默认 204800），主任务栈
559	     * 远不够。cloud_init 也放这里，避免主线程先初始化造成竞争。 */
560	    cloud_init();
561	
562	    /* 联网已由主线程在创建工作线程之前完成（见 main()）：
563	     * 驱动初始化里的 mallinfo() 不能与其它线程的分配并发。 */
564	
565	    printf("[Main] 云端健康检查...\n");
566	    if (cloud_health_check() != CLOUD_OK) {
567	        printf("[Main] 警告: 云端不可达，请检查 CLOUD_URL 与网络\n");
568	    }
569	
570	    /* 账号绑定（2026-10-27）：没绑定就申请一个 token，把二维码 URL 交给主线程。
571	     * token 同时是设备之后的长期凭据，申请到立刻落盘（重启不再重复申请）。 */
572	    if (cloud_user_token()[0] == '\0') {
573	        char bind_url[256];
574	        char bind_token[128];
575	
576	        printf("[Main] 未绑定账号，向云端申请绑定二维码...\n");
577	        if (cloud_bind_start(bind_url, sizeof(bind_url),
578	                             bind_token, sizeof(bind_token)) == CLOUD_OK) {
579	            cloud_set_user_token(bind_token);
580	            save_user_token(bind_token);
581	            publish_bind_url(bind_url);
582	        } else {
583	            printf("[Main] 申请绑定二维码失败（不影响面试，重启可再试）\n");
584	        }
585	    }
586	
587	    for (;;) {
588	        app_cmd_t cmd;
589	        char discard_sid[64];
590	
591	        /* ---- 待处理的"舍弃本场"通知（K2 长按设置）----
592	         * 网络调用必须留在工作线程：主循环每 100ms 一拍，塞个最多 30 秒的 HTTP
593	         * 进去，按键和 LED 都会僵住（同文件顶部的线程模型注释）。
594	         * 忙的时候它排在下一轮之后 —— 没关系：长按同时置了 g_abort，当前这一轮
595	         * 会很快退出，然后这里就把 DELETE 发出去。 */
596	        pthread_mutex_lock(&g_lock);
597	        strncpy(discard_sid, g_discard_sid, sizeof(discard_sid) - 1);
598	        discard_sid[sizeof(discard_sid) - 1] = '\0';
599	        g_discard_sid[0] = '\0';
600	        pthread_mutex_unlock(&g_lock);
601	
602	        if (discard_sid[0] != '\0') {
603	            printf("[Main] 通知云端删除本场记录（session=%s）...\n", discard_sid);
604	            if (cloud_discard_session(discard_sid) == CLOUD_OK) {
605	                printf("[Main] 云端记录已删除（/history 里不会再出现）\n");
606	            } else {
607	                printf("[Main] 警告: 云端删除失败 —— /history 里可能仍显示「进行中」\n");
608	            }
609	        }
610	
611	        pthread_mutex_lock(&g_lock);
612	        cmd = g_cmd;
613	        g_cmd = CMD_NONE;
614	        pthread_mutex_unlock(&g_lock);
615	
616	        /* 屏幕配网页提交 → 凭据已由主线程写盘（见 app_wifi_setup），
617	         * 这里只负责真正执行连接（会阻塞几秒，所以必须在本线程）。 */
618	        if (cmd == CMD_WIFI_CONNECT) {
619	            printf("[Main] 收到屏幕配网请求，开始连接...\n");
620	            if (wifi_connect_boot() == 0) {
621	                printf("[Main] Wi-Fi 连接命令已完成（以云端健康检查为准）\n");
622	            } else {
623	                printf("[Main] Wi-Fi 连接未完成 —— 可在屏幕上重新设置\n");
624	            }
625	            continue;
626	        }
627	
628	        if (cmd != CMD_START) {
629	            usleep(MAIN_LOOP_MS * 1000 / 2);
630	            continue;
631	        }
632	
633	        pthread_mutex_lock(&g_lock);
634	        g_worker_busy = 1;
635	        g_abort = 0;
636	        pthread_mutex_unlock(&g_lock);
637	
638	        run_one_round();
639	
640	        pthread_mutex_lock(&g_lock);
641	        g_worker_busy = 0;
642	        pthread_mutex_unlock(&g_lock);
643	    }
644	
645	    return NULL;
646	}
