650	static int read_button(int fd)
651	{
652	    bool value = false;
653	
654	    if (fd < 0) {
655	        return -1;
656	    }
657	    ioctl(fd, GPIOC_READ, (unsigned long)((uintptr_t)&value));
658	    return value ? 1 : 0;
659	}

660	
661	/*
662	 * 取"上次状态"的初值。
663	 *
664	 * 不能直接假定为 1（松开）：这几个脚配的是下拉，K2/K3 悬空或未接时
665	 * 读到的是低电平，初值取 1 就会在开机第一次扫描时误判成一次"按下"。
666	 * 实测开机时 K2、K3 各误触发一次 —— K2 那次会把 g_abort 置 1；更要命的是
667	 * 万一它抢在 K1 前面，状态机会从 IDLE 直接进 RECORDING，而工作线程压根
668	 * 没收到 CMD_START，整机就卡在"录音中"了。
669	 *
670	 * fd 打不开时返回 1（维持原行为）：这种情形按键本来就用不了，
671	 * 循环里的 read_button() 会一直返回 -1，产生不了边沿。
672	 */
673	static int read_button_initial(int fd)
674	{
675	    int s = read_button(fd);
676	
677	    return (s < 0) ? 1 : s;
678	}
679	
680	static void init_buttons(void)
681	{
682	    g_key1_fd = open("/dev/gpio1", O_RDWR);
683	    if (g_key1_fd < 0) {
684	        printf("[Main] 警告: 无法打开 K1 GPIO (GPIO1)\n");
685	    } else {
686	        ioctl(g_key1_fd, GPIOC_SETPINTYPE, GPIO_INPUT_PIN_PULLDOWN);
687	        printf("[Main] K1 GPIO (GPIO1) 初始化成功\n");
688	    }
689	
690	    g_key2_fd = open("/dev/gpio3", O_RDWR);
691	    if (g_key2_fd < 0) {
692	        printf("[Main] 警告: 无法打开 K2 GPIO (GPIO3)\n");
693	    } else {
694	        ioctl(g_key2_fd, GPIOC_SETPINTYPE, GPIO_INPUT_PIN_PULLDOWN);
695	        printf("[Main] K2 GPIO (GPIO3) 初始化成功\n");
696	    }
697	
698	    g_key3_fd = open("/dev/gpio4", O_RDWR);
699	    if (g_key3_fd < 0) {
700	        printf("[Main] 警告: 无法打开 K3 GPIO (GPIO4)\n");
701	    } else {
702	        ioctl(g_key3_fd, GPIOC_SETPINTYPE, GPIO_INPUT_PIN_PULLDOWN);
703	        printf("[Main] K3 GPIO (GPIO4) 初始化成功\n");
704	    }
705	
706	    /* 初值取自实际电平，避免开机瞬间的假边沿 */
707	    g_key1_last = read_button_initial(g_key1_fd);
708	    g_key2_last = read_button_initial(g_key2_fd);
709	    g_key3_last = read_button_initial(g_key3_fd);
710	}
711	
712	static void check_buttons(void)
713	{
714	    int s1 = read_button(g_key1_fd);
715	    int s2 = read_button(g_key2_fd);
716	    int s3 = read_button(g_key3_fd);
717	    int busy;
718	
719	    pthread_mutex_lock(&g_lock);
720	    busy = g_worker_busy;
721	    pthread_mutex_unlock(&g_lock);
722	
723	    /* K1 下降沿：开始一轮。忙碌时忽略，避免重入 */
724	    if (s1 == 0 && g_key1_last == 1) {
725	        if (busy) {
726	            printf("[Main] K1 按下，但正在进行中，忽略\n");
727	        } else {
728	            printf("[Main] K1 按下 —— 开始面试\n");
729	            pthread_mutex_lock(&g_lock);
730	            g_cmd = CMD_START;
731	            pthread_mutex_unlock(&g_lock);
732	            state_machine_post_event(EVENT_BUTTON_PRESS);  /* -> RECORDING */
733	        }
734	    }
735	    g_key1_last = s1;
736	
737	    /* K2 下降沿：取消当前一轮 / 从错误态返回。
738	     *
739	     * ⚠️ 这里必须**问状态机**，不能从 `busy` 反推。早先写的是「不忙碌时说明停在
740	     * ERROR 态」→ 投 EVENT_BUTTON_PRESS 回 IDLE。那个假设是错的：`!busy` 在
741	     * **IDLE 同样成立**。于是待机时按一下 K2，状态机会被推进 RECORDING
742	     * （state_machine.c 的 `IDLE --BUTTON_PRESS--> RECORDING`），而工作线程根本
743	     * 没收到 CMD_START —— LED1 快闪、其实什么都没录，**且没有任何超时能把它救
744	     * 出来**（EVENT_RECORD_TIMEOUT 全仓没有一个投递点）。只能靠再按 K1 把它带回
745	     * 正轨，可那已经不是"取消"，是把机器弄糊涂了。
746	     */
747	    if (s2 == 0 && g_key2_last == 1) {
748	        if (busy) {
749	            /* 有活在跑：置 abort，工作线程会在 100ms 粒度内退出 */
750	            printf("[Main] K2 按下 —— 取消当前一轮\n");
751	            g_abort = 1;
752	        } else if (state_machine_get_current_state() == STATE_ERROR) {
753	            /* 真的停在错误态，按一下回待机。状态机调用放在锁外：
754	             * 持锁做 ioctl/printf 没有必要。 */
755	            printf("[Main] K2 按下 —— 从错误态返回待机\n");
756	            state_machine_post_event(EVENT_BUTTON_PRESS);
757	        } else {
758	            int has_session;
759	
760	            pthread_mutex_lock(&g_lock);
761	            has_session = (g_session_id[0] != '\0');
762	            pthread_mutex_unlock(&g_lock);
763	
764	            if (!has_session) {
765	                /* 面试开始前：K2 循环切换压力档位（2026-10-19，三档照搬 myagent）。
766	                 * 标准 → 压力 → 温和 → 标准。会话一旦建立就钉死。 */
767	                g_pressure_idx = (g_pressure_idx + 1) % APP_PRESSURE_COUNT;
768	                printf("[Main] K2 按下 —— 压力档位切换为「%s」（%d/%d）\n",
769	                       current_pressure(), g_pressure_idx + 1, APP_PRESSURE_COUNT);
770	                state_machine_flash(2);
771	                interview_ui_set_pressure(current_pressure());
772	            } else {
773	                /* 待机但本场还没结束（场间）：没有可取消的东西。
774	                 * 顺带不置 g_abort —— 在待机置它只会让下一轮在起跑线上被中止。 */
775	                printf("[Main] K2 按下 —— 当前待机，无操作（长按可舍弃本场）\n");
776	            }
777	        }
778	    }
779	    /* K2 **长按** ~1.5 秒：舍弃本场（2026-10-18 加）。
780	     *
781	     * 场景：误触 K1、岗位选错了 —— 直接放弃这一场、**不生成报告**，省掉一轮
782	     * LLM+TTS 的时间。做法：置 g_abort（正在跑的一轮尽快退出）+ 清 g_session_id
783	     * （云端那场不再继续，永远走不到出报告那一轮）。云端只在 /history 里留一条
784	     * "未结束"的记录。
785	     *
786	     * 短按行为不变：进行中 = 取消本轮；错误态 = 回待机；待机 = 无操作。
787	     */
788	    /* ⚠️ 电平极性（2026-10-18 第一版写反了，真机当场暴露）：这几个键**按下 = 高电平**
789	     * （见 read_button_initial 的注释：松开/悬空时读到低电平，所以上面的短按逻辑是在
790	     * 1→0 的"松开沿"触发）。长按计数必须数 **s2 == 1** 的拍数 —— 写成 s2 == 0 的后果是
791	     * "没按键也在数"：会话一出现，1.5 秒后就自动舍弃本场（用户实测：面试官刚说 2 秒就被判长按）。 */
792	    if (s2 == 1) {
793	        int has_session;
794	
795	        pthread_mutex_lock(&g_lock);
796	        has_session = (g_session_id[0] != '\0');
797	        pthread_mutex_unlock(&g_lock);
798	
799	        if (has_session) {
800	            if (g_key2_hold <= K2_DISCARD_TICKS) {
801	                g_key2_hold++;
802	            }
803	            if (g_key2_hold == K2_DISCARD_TICKS) {
804	                printf("[Main] K2 长按 —— 舍弃本场（不生成报告，并删除本场记录），回到待机\n");
805	                g_abort = 1;                     /* 正在录音/上传/播放的话尽快退出 */
806	                pthread_mutex_lock(&g_lock);
807	                strncpy(g_discard_sid, g_session_id, sizeof(g_discard_sid) - 1);
808	                g_discard_sid[sizeof(g_discard_sid) - 1] = '\0';
809	                g_session_id[0] = '\0';
810	                pthread_mutex_unlock(&g_lock);
811	                /* 真正的删除由工作线程发（见 pipeline_worker 开头）——
812	                 * 用户要的是"连记录都不要"，所以不是留在 /history 里当"未结束"。 */
813	            }
814	        } else {
815	            g_key2_hold = 0;
816	        }
817	    } else {
818	        g_key2_hold = 0;
819	    }
820	    g_key2_last = s2;
821	
822	    /* K3 下降沿：在两场面试之间循环切换岗位。
823	     *
824	     * 为什么必须"两场之间"：云端出题按**请求里的** role，但报告 / 评分 / 导出按
825	     * **建会话时的** role —— 中途换会让一场面试出现两种岗位（题变了、报告还是旧的）。
826	     * 所以会话没结束（`g_session_id` 非空）时只提示，不切。
827	     */
828	    if (s3 == 0 && g_key3_last == 1) {
829	        int session_live;
830	
831	        pthread_mutex_lock(&g_lock);
832	        session_live = (g_session_id[0] != '\0');
833	        pthread_mutex_unlock(&g_lock);
834	
835	        if (busy) {
836	            printf("[Main] K3 按下，但正在进行中 —— 等这一轮跑完再按\n");
837	        } else if (session_live) {
838	            printf("[Main] K3 按下 —— 本场面试还没结束（题和报告要用同一个岗位），"
839	                   "等报告出来再按；要强制换就重启设备\n");
840	        } else {
841	            int cur = (g_role_idx >= 0) ? g_role_idx : app_role_index(app_role());
842	
843	            g_role_idx = (cur + 1) % APP_ROLE_COUNT;
844	            printf("[Main] K3 按下 —— 岗位切换为「%s」（%d/%d）\n",
845	                   current_role(), g_role_idx + 1, APP_ROLE_COUNT);
846	            state_machine_flash(2);
847	            interview_ui_set_role(current_role());   /* 屏上岗位立刻跟着变 */
848	        }
849	    }
850	    g_key3_last = s3;
851	}
