209	void state_machine_update_led(void)
210	{
211	    /* 正在"确认闪"：接管 LED1，闪完自动交还 */
212	    if (g_flash_left > 0) {
213	        led1_write(((g_flash_phase / FLASH_HALF_TICKS) % 2) == 0);
214	        led2_write(0);
215	        g_flash_phase++;
216	        g_flash_left--;
217	        if (g_flash_left == 0) {
218	            g_flash_phase = 0;
219	            g_led_tick = 0;
220	            g_led_tick_state = g_current_state;
221	        }
222	        return;
223	    }
224	
225	    /* 换状态就把节拍归零：图案从头开始，"三短闪"才真的是三下，而不是从某个
226	     * 相位中途接上（否则可能看起来只有两下）。 */
227	    if (g_current_state != g_led_tick_state) {
228	        g_led_tick_state = g_current_state;
229	        g_led_tick = 0;
230	    }
231	
232	    switch (g_current_state) {
233	        case STATE_IDLE:
234	            /* 待机: LED1 常亮 */
235	            led1_write(1);
236	            break;
237	
238	        case STATE_RECORDING:
239	            /* 录音中: LED1 快闪（200ms 一侧）*/
240	            led1_write(blink_square(g_led_tick, BLINK_HALF_FAST));
241	            break;
242	
243	        case STATE_UPLOADING:
244	            /* 上传中: LED1 慢闪（800ms 一侧）—— 与录音的差别只在这个常数，
245	             * 而原实现里两个分支写的是同一段代码，所以实际闪得一样快。 */
246	            led1_write(blink_square(g_led_tick, BLINK_HALF_SLOW));
247	            break;
248	
249	        case STATE_PLAYING:
250	            /* 播放中: LED2 常亮 */
251	            led2_write(1);
252	            break;
253	
254	        case STATE_ERROR:
255	            /* 错误: 三短闪 + 停顿。一个 12 tick 的循环：前 6 tick 里隔一个亮
256	             * 一个（亮 1、灭 1、亮 1、灭 1、亮 1 —— 即三下短闪），后 6 tick 全灭。*/
257	            led1_write((g_led_tick % ERROR_CYCLE_TICKS) < 6
258	                       && (g_led_tick % 2) == 0);
259	            break;
260	    }
261	
262	    /* 先把当前相位渲染出去，再推进节拍 —— 这样换状态后的第一次调用用的是
263	     * tick=0，图案起点是确定的。 */
264	    g_led_tick++;
265	}
