76	static int g_retry_count = 0;
77	#define MAX_RETRY_COUNT 3
78	
79	static const char* state_names[] = {"IDLE", "RECORDING", "UPLOADING", "PLAYING", "ERROR"};
80	static const char* event_names[] = {"BUTTON_PRESS", "RECORD_DONE", "RECORD_TIMEOUT", "UPLOAD_SUCCESS", "UPLOAD_FAIL", "PLAY_DONE", "RETRY", "ERROR"};
81	
82	static system_state_t get_next_state(system_state_t current, system_event_t event)
83	{
84	    switch (current) {
85	        case STATE_IDLE:
86	            if (event == EVENT_BUTTON_PRESS) { g_retry_count = 0; return STATE_RECORDING; }
87	            return current;
88	        case STATE_RECORDING:
89	            if (event == EVENT_RECORD_DONE || event == EVENT_RECORD_TIMEOUT) return STATE_UPLOADING;
90	            if (event == EVENT_ERROR) return STATE_IDLE;
91	            return current;
92	        case STATE_UPLOADING:
93	            if (event == EVENT_UPLOAD_SUCCESS) return STATE_PLAYING;
94	            if (event == EVENT_UPLOAD_FAIL) {
95	                g_retry_count++;
96	                if (g_retry_count >= MAX_RETRY_COUNT) return STATE_IDLE;
97	                return STATE_ERROR;
98	            }
99	            /* 上传期间按 K2 取消 —— 与录音阶段用同一个事件（RECORDING 也是
100	             * `--ERROR--> IDLE`），两条取消路径的行为因此完全一致。
101	             * 少了这一条，从 UPLOADING 发 EVENT_ERROR 会被静默忽略、
102	             * 状态机卡在上传态（这正是 §11.26 那次"按下取消却走完三次重试"
103	             * 的另一半原因：标志置了、循环不看、事件也没人接）。 */
104	            if (event == EVENT_ERROR) return STATE_IDLE;
105	            return current;
106	        case STATE_PLAYING:
107	            if (event == EVENT_PLAY_DONE) return STATE_IDLE;
108	            return current;
109	        case STATE_ERROR:
110	            if (event == EVENT_BUTTON_PRESS) { g_retry_count = 0; return STATE_IDLE; }
111	            if (event == EVENT_RETRY) return STATE_UPLOADING;
112	            return current;
113	    }
114	    return STATE_IDLE;
115	}
