220	/* 一排「- 音量 X% +」；两页各建一份，label 指针留给 set_volume 更新。
221	 *
222	 * ⚠️ 贴底摆放（2026-10-19 真机修正）：第一版按"屏幕中心 +225"摆，用户实测
223	 * **整排完全看不见** —— 屏的可用高度不一定是我们以为的 800（fb 分辨率由驱动
224	 * 决定，面板 800×1280 经硬件旋转后也可能是别的值），固定偏移一旦超出就整排
225	 * 在屏外。贴到父对象底边后，无论分辨率多少都落在屏幕内。
226	 * 小屏（high < 480）同时把按钮缩到 44、边距收到 6，给上面的文字留空间。 */
227	static void build_volume_row(lv_obj_t *parent, lv_obj_t **label_out, int compact)
228	{
229	    int size = compact ? 44 : 64;
230	    int edge = compact ? 6 : 16;
231	    int gap  = compact ? 75 : 95;
232	    lv_obj_t *row = lv_obj_create(parent);
233	    lv_obj_t *minus;
234	    lv_obj_t *plus;
235	
236	    lv_obj_set_size(row, LV_PCT(100), size);
237	    lv_obj_align(row, LV_ALIGN_BOTTOM_MID, 0, -edge);
238	    lv_obj_set_style_bg_opa(row, LV_OPA_TRANSP, 0);
239	    lv_obj_set_style_border_width(row, 0, 0);
240	    lv_obj_set_style_pad_all(row, 0, 0);
241	    lv_obj_remove_flag(row, LV_OBJ_FLAG_SCROLLABLE);
242	
243	    minus = make_volume_button(row, "-", -1, size);
244	    plus  = make_volume_button(row, "+", +1, size);
245	
246	    *label_out = make_label(row, "音量 60%", g_font_hint, UI_TEXT_COLOR,
247	                            LV_ALIGN_CENTER, 0, 0);
248	    lv_obj_align(minus, LV_ALIGN_CENTER, -gap, 0);
249	    lv_obj_align(plus, LV_ALIGN_CENTER, gap, 0);
250	}
