558	
559	int interview_ui_init(void)
560	{
561	    static lv_nuttx_result_t result;
562	    lv_nuttx_dsc_t info;
563	
564	    if (!lv_is_initialized()) {
565	        lv_init();
566	
567	        lv_nuttx_dsc_init(&info);
568	#ifdef CONFIG_LV_USE_NUTTX_LCD
569	        info.fb_path = "/dev/lcd0";
570	#endif
571	#ifdef CONFIG_INPUT_TOUCHSCREEN
572	        /* 触摸屏：屏上音量控件要它（2026-10-19）。设备名同打地鼠。 */
573	        info.input_path = UI_TOUCH_PATH;
574	#endif
575	        /* 触摸这一版不用（设计见头文件）—— 不填 input_path，LVGL 就没有输入设备 */
576	        lv_nuttx_init(&info, &result);
577	
578	        if (result.disp == NULL) {
579	            printf("[UI] 显示屏初始化失败 —— 本次不带屏运行\n");
580	            return -1;
581	        }
582	
583	        /* 触摸排障用（2026-10-19）：第一版音量控件"完全没显示"，先确认
584	         * 输入设备到底有没有接上。点按钮时 main.c 还会打「音量：X%」。 */
585	        printf("[UI] 触摸输入 %s（%s）\n",
586	               result.indev != NULL ? "已接上" : "未接上", UI_TOUCH_PATH);
587	    } else if (lv_display_get_default() == NULL) {
588	        /* 别的应用（如打地鼠）初始化过 LVGL 又没留下可用的显示 —— 同样退化。
589	         * 本应用重启后能复用已初始化的 LVGL，靠的就是上面这条分支。 */
590	        printf("[UI] LVGL 已初始化但没有可用显示 —— 本次不带屏运行\n");
591	        return -1;
592	    }
593	
594	    {
595	        /* 排障用：实际 fb 分辨率决定布局（见 build_volume_row 的注释）。 */
596	        lv_display_t *disp = lv_display_get_default();
597	
598	        if (disp != NULL) {
599	            printf("[UI] 屏幕分辨率 %d×%d\n",
600	                   (int)lv_display_get_horizontal_resolution(disp),
601	                   (int)lv_display_get_vertical_resolution(disp));
602	        }
603	    }
604	
605	    g_font_title = load_font(UI_FONT_TITLE, lv_font_default());
606	    g_font_body  = load_font(UI_FONT_BODY,  lv_font_default());
607	    g_font_hint  = load_font(UI_FONT_HINT,  lv_font_default());
608	
609	    build_idle_page();
610	    build_live_page();
611	    build_wifi_page();
612	    build_bind_page();
613	
