203	/* 待机页「− 轮数：10 +」：在预设表里往前/往后走一格（边界处不动）。 */
204	static void app_rounds_step(int delta)
205	{
206	    int i;
207	    int idx = 0;
208	    int best = -1;
209	
210	    /* 当前值不一定正好是预设（例如串口写了 7）—— 先找最近的预设。 */
211	    for (i = 0; i < ROUND_PRESET_COUNT; i++) {
212	        int diff = g_round_presets[i] - g_target_rounds;
213	        int dist = (diff < 0) ? -diff : diff;
214	
215	        if (best < 0 || dist < best) {
216	            best = dist;
217	            idx = i;
218	        }
219	    }
220	
221	    if (delta < 0 && idx > 0) {
222	        idx--;
223	    } else if (delta > 0 && idx < ROUND_PRESET_COUNT - 1) {
224	        idx++;
225	    }
226	
227	    g_target_rounds = g_round_presets[idx];
228	    save_rounds_pref();
229	    cloud_set_target_rounds(g_target_rounds);
230	    interview_ui_set_rounds(g_target_rounds);
231	    printf("[Main] 面试轮数：%d（报告在第 %d 次回答后出；下一场生效）\n",
232	           g_target_rounds, g_target_rounds + 1);
233	}
