235	/* ---- 账号 token（2026-10-27）----
236	 * 扫码绑定后设备拿到的长期凭据，随每次面试请求发送；存在 /data 的一个小文件里。
237	 * token 由云端 /api/bind/start 生成，**同时就是二维码里的绑定码**：
238	 * 设备申请到就立刻落盘并用它请求，手机扫码后云端把 token 与账号关联。 */
239	#define USER_PREF_PATH "/data/ai_interview_user"
240	static char g_user_token[128];
241	static char g_bind_url[256];
242	static int  g_bind_url_pending;
243	
244	static void trim_eol(char *s)
245	{
246	    size_t len = strlen(s);
247	    while (len > 0 && (s[len - 1] == '\r' || s[len - 1] == '\n' ||
248	                       s[len - 1] == ' ' || s[len - 1] == '\t')) {
249	        s[--len] = '\0';
250	    }
251	}
252	
253	static void load_user_token(void)
254	{
255	    FILE *fp = fopen(USER_PREF_PATH, "r");
256	
257	    g_user_token[0] = '\0';
258	    if (fp == NULL) {
259	        return;                     /* 还没绑定 */
260	    }
261	    if (fgets(g_user_token, sizeof(g_user_token), fp) != NULL) {
262	        trim_eol(g_user_token);
263	        if (g_user_token[0] != '\0') {
264	            printf("[Main] 账号 token：已加载（%s）\n", USER_PREF_PATH);
265	        }
266	    }
267	    fclose(fp);
268	}
