284	/* 工作线程 → 主线程：二维码 URL 通过共享槽传递（LVGL 只归主线程碰）。 */
285	static void publish_bind_url(const char *url)
286	{
287	    pthread_mutex_lock(&g_lock);
288	    strncpy(g_bind_url, url, sizeof(g_bind_url) - 1);
289	    g_bind_url[sizeof(g_bind_url) - 1] = '\0';
290	    g_bind_url_pending = 1;
291	    pthread_mutex_unlock(&g_lock);
292	}
293	
294	static int take_bind_url(char *out, size_t cap)
295	{
296	    int pending;
297	
298	    pthread_mutex_lock(&g_lock);
299	    pending = g_bind_url_pending;
300	    if (pending) {
301	        strncpy(out, g_bind_url, cap - 1);
302	        out[cap - 1] = '\0';
303	        g_bind_url_pending = 0;
304	    }
305	    pthread_mutex_unlock(&g_lock);
306	    return pending;
307	}
