/* ---- 开机/用网期间的"网络不可用"状态（2026-11-03，断网提示补缺）----
 * §11.78记的缺口：开机没联网时屏幕一声不吭。健康检查失败就把这个标志立起来，
 * 主循环据此提示「网络未连接…」；恢复后自动收起（空闲时定期探测）。 */
static int g_net_down;

static void set_net_down(int down)
{
    pthread_mutex_lock(&g_lock);
    g_net_down = down ? 1 : 0;
    pthread_mutex_unlock(&g_lock);
}

static int app_net_down(void)
{
    int down;

    pthread_mutex_lock(&g_lock);
    down = g_net_down;
    pthread_mutex_unlock(&g_lock);
    return down;
}
