/* 断网提示（2026-11-02 第 1 层 + 11-03 补开机缺口）：
 *   有待补送的音频 →「网络断开，按 K2 重试」（优先，可操作）；
 *   只是网络不可用 →「网络未连接 —— 可在右上角「Wi-Fi」重新配置」。
 * 都跟着状态标志自愈：补送成功 / 舍弃本场 / 网络恢复都会自动收起。 */
{
    const char *msg = NULL;

    if (app_has_pending()) {
        msg = "网络断开，按 K2 重试";
    } else if (app_net_down()) {
        msg = "网络未连接 —— 可在右上角「Wi-Fi」重新配置";
    }
    if (msg != NULL) {
        if (strcmp(g_ui_hint_text, msg) != 0) {
            strncpy(g_ui_hint_text, msg, sizeof(g_ui_hint_text) - 1);
            g_ui_hint_text[sizeof(g_ui_hint_text) - 1] = '\0';
            g_ui_hint_visible = 1;
            interview_ui_set_hint(msg);
        }
    } else if (g_ui_hint_visible) {
        g_ui_hint_visible = 0;
        g_ui_hint_text[0] = '\0';
        interview_ui_set_hint(NULL);
    }
}

